import { timeFrameLabelMatcher } from "./timeFrameLabelMatcher";
export const getTimeRangeForTimeFrame = (timeFrame, flattenedPresets, now, onParse, units) => {
    const preset = flattenedPresets.find(timeFrameLabelMatcher(timeFrame));
    if (preset) {
        return "onParse" in preset ? preset.onParse(now) : preset.value;
    }
    const normalisedTimeFrame = timeFrame.trim().toLowerCase();
    const [, , unit] = normalisedTimeFrame.split(" ");
    if (!units.some((validUnits) => unit?.startsWith(validUnits))) {
        return undefined;
    }
    if (typeof onParse === "function") {
        return onParse(timeFrame, now);
    }
    return undefined;
};
